4486			return -ENODEV;
4487		}
4488	#endif
4489	
4490		atomic_clear_bit(hdev->flags, BT_DEV_DISABLE);
4491	
4492		if (atomic_test_and_set_bit(hdev->flags, BT_DEV_ENABLE)) {
4493			if (cb) {
4494				cb(hdev->dev_id, 0);
4495			}
4496			return 0;
4497		}
4498	
4499	#if defined(CONFIG_BT_SMP) || defined(CONFIG_BT_CLASSIC)
4500		bt_keys_reset(hdev);
4501	#endif
4502	
4503		if (IS_ENABLED(CONFIG_BT_SETTINGS)) {
4504			err = bt_settings_init(hdev);
4505			if (err) {
4506				return err;
4507			}
4508		} else if (IS_ENABLED(CONFIG_BT_DEVICE_NAME_DYNAMIC)) {
4509			err = bt_set_name_mc(dev_id, CONFIG_BT_DEVICE_NAME);
4510			if (err) {
4511				LOG_WRN("Failed to set device name (%d)", err);
4512			}
4513		}
4514	
4515		hdev->ready_cb = cb;
4516	
4517		/* Give cmd_sem allowing to send first HCI_Reset cmd, the only
4518		 * exception is if the controller requests to wait for an
4519		 * initial Command Complete for NOP.
4520		 */
4521		if (!IS_ENABLED(CONFIG_BT_WAIT_NOP)) {
4522			k_sem_init(&hdev->ncmd_sem, 1, 1);
4523		} else {
4524			k_sem_init(&hdev->ncmd_sem, 0, 1);
4525		}
4526		k_fifo_init(&hdev->cmd_tx_queue);
4527	
4528	#if defined(CONFIG_BT_RECV_WORKQ_BT)
4529		/* RX thread */
4530		if (bt_workq.flags & K_WORK_QUEUE_STARTED) {
4531			LOG_DBG("Work queue already started");
4532		} else {
4533			k_work_queue_init(&bt_workq);
4534			k_work_queue_start(&bt_workq, rx_thread_stack,
4535					CONFIG_BT_RX_STACK_SIZE,
4536					K_PRIO_COOP(CONFIG_BT_RX_PRIO), NULL);
4537			k_thread_name_set(&bt_workq.thread, "BT RX WQ");
4538		}	
4539	#endif
4540	
4541		k_work_init(&hdev->rx_work, rx_work_handler);
4542		k_work_init(&hdev->tx_work, tx_work_handler);
4543	
4544	#if DT_HAS_CHOSEN(zephyr_bt_hci)
4545		err = bt_hci_open(hdev->hci, bt_hci_recv, hdev);
4546	#else
4547		err = hdev->drv->open();
4548	#endif
4549		if (err) {
4550			LOG_ERR("HCI driver open failed (%d)", err);
4551			return err;
4552		}
4553	
4554		bt_monitor_send(BT_MONITOR_OPEN_INDEX, NULL, 0);
4555	
4556		if (!cb) {
4557			return bt_init(hdev);
4558		}
4559	
4560		k_work_submit(&hdev->init);
4561		return 0;
4562	}
