4564	int bt_disable_mc(uint8_t dev_id)
4565	{
4566		int err;
4567		struct bt_dev *hdev;
4568	
4569		hdev = bt_dev_get(dev_id);
4570		if (!hdev) {
4571			return -ENODEV;
4572		}
4573	
4574	#if !DT_HAS_CHOSEN(zephyr_bt_hci)
4575		if (!hdev->drv) {
4576			LOG_ERR("No HCI driver registered");
4577			bt_dev_free(hdev);
4578			return -ENODEV;
4579		}
4580	
4581		if (!hdev->drv->close) {
4582			bt_dev_free(hdev);
4583			return -ENOTSUP;
4584		}
4585	#endif
4586	
4587		if (atomic_test_and_set_bit(hdev->flags, BT_DEV_DISABLE)) {
4588			bt_dev_free(hdev);
4589			return -EALREADY;
4590		}
4591	
4592		/* Clear BT_DEV_READY before disabling HCI link */
4593		atomic_clear_bit(hdev->flags, BT_DEV_READY);
4594	
4595	#if defined(CONFIG_BT_BROADCASTER)
4596		bt_adv_reset_adv_pool(hdev);
4597	#endif /* CONFIG_BT_BROADCASTER */
4598	
4599	#if defined(CONFIG_BT_PRIVACY)
4600		k_work_cancel_delayable(&hdev->rpa_update);
4601	#endif /* CONFIG_BT_PRIVACY */
4602	
4603	#if defined(CONFIG_BT_PER_ADV_SYNC)
4604		bt_periodic_sync_disable(hdev);
4605	#endif /* CONFIG_BT_PER_ADV_SYNC */
4606	
4607	#if defined(CONFIG_BT_CONN)
4608		if (IS_ENABLED(CONFIG_BT_SMP)) {
4609			bt_pub_key_hci_disrupted(hdev);
4610		}
4611		bt_conn_cleanup_all(hdev);
4612		disconnected_handles_reset(hdev);
4613	#endif /* CONFIG_BT_CONN */
4614	
4615		/* Reset the Controller */
4616		if (!drv_quirk_no_reset(hdev)) {
4617	
4618			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_RESET, NULL, NULL);
4619			if (err) {
4620				LOG_ERR("Failed to reset BLE controller");
4621				return err;
4622			}
4623	
4624			hci_reset_complete(hdev);
4625		}
4626	
4627	#if DT_HAS_CHOSEN(zephyr_bt_hci)
4628		err = bt_hci_close(hdev->hci);
4629		if (err == -ENOSYS) {
4630			atomic_clear_bit(hdev->flags, BT_DEV_DISABLE);
4631			atomic_set_bit(hdev->flags, BT_DEV_READY);
4632			bt_dev_free(hdev);
4633			return -ENOTSUP;
4634		}
4635	#else
4636		err = hdev->drv->close();
4637	#endif
4638		if (err) {
4639			LOG_ERR("HCI driver close failed (%d)", err);
4640	
4641			/* Re-enable BT_DEV_READY to avoid inconsistent stack state */
4642			atomic_set_bit(hdev->flags, BT_DEV_READY);
4643			bt_dev_free(hdev);
4644	
4645			return err;
4646		}
4647	
4648	#if defined(CONFIG_BT_RECV_WORKQ_BT)
4649		/* Abort RX thread */
4650		k_thread_abort(&bt_workq.thread);
4651		bt_workq.flags &= ~K_WORK_QUEUE_STARTED;
4652	#endif
4653	
4654		/* Some functions rely on checking this bitfield */
4655		memset(hdev->supported_commands, 0x00, sizeof(hdev->supported_commands));
4656	
4657		/* Reset IDs and corresponding keys. */
4658		hdev->id_count = 0;
4659	#if defined(CONFIG_BT_SMP)
4660		hdev->le.rl_entries = 0;
4661	#endif
4662	
4663	#if defined(CONFIG_BT_SMP) || defined(CONFIG_BT_CLASSIC)
4664		bt_keys_reset(hdev);
4665	#endif
4666		/* If random address was set up - clear it */
4667		bt_addr_le_copy(&hdev->random_addr, BT_ADDR_LE_ANY);
4668	
4669		if (IS_ENABLED(CONFIG_BT_ISO)) {
4670			bt_iso_reset(hdev);
4671		}
4672	
4673		bt_monitor_send(BT_MONITOR_CLOSE_INDEX, NULL, 0);
4674	
4675		/* Clear BT_DEV_ENABLE here to prevent early bt_enable() calls, before disable is
4676		 * completed.
4677		 */
4678		atomic_clear_bit(hdev->flags, BT_DEV_ENABLE);
4679	
4680		bt_dev_free(hdev);
4681	
4682		return 0;
4683	}
