 78	static int h4_recv_data(uint8_t *buf, size_t count)
 79	{
 80		ssize_t ret, nread = 0;
 81	
 82		while (count != nread) {
 83			ret = file_read(&g_filep, buf + nread, count - nread);
 84			if (ret < 0) {
 85				return ret;
 86			}
 87	
 88			nread += ret;
 89		}
 90	
 91		return nread;
 92	}
 93	
 94	static int h4_send_data(uint8_t *buf, size_t count)
 95	{
 96		ssize_t ret, nwritten = 0;
 97	
 98		while (nwritten != count) {
 99			ret = file_write(&g_filep, buf + nwritten, count - nwritten);
100			if (ret < 0) {
101				return ret;
102			}
103	
104			nwritten += ret;
105		}
106	
107		return nwritten;
108	}
