115	/* Function expects that type is validated and only CMD, ISO or ACL will be used. */
116	static uint32_t get_len(const uint8_t *hdr_buf, uint8_t type)
117	{
118		switch (type) {
119		case H4_CMD:
120			return ((const struct bt_hci_cmd_hdr *)hdr_buf)->param_len;
121		case H4_ISO:
122			return bt_iso_hdr_len(
123				((const struct bt_hci_iso_hdr *)hdr_buf)->len);
124		case H4_ACL:
125			return ((const struct bt_hci_acl_hdr *)hdr_buf)->len;
126		default:
127			LOG_ERR("Invalid type: %u", type);
128			return 0;
129		}
130	}
