132	static int hdrlen(uint8_t type)
133	{
134		switch (type) {
135		case H4_CMD:
136			return sizeof(struct bt_hci_cmd_hdr);
137		case H4_ISO:
138			return sizeof(struct bt_hci_iso_hdr);
139		case H4_ACL:
140			return sizeof(struct bt_hci_acl_hdr);
141		default:
142			LOG_ERR("Invalid type: %u", type);
143			return 0;
144		}
