147	static void h4_tx_thread(void *p1, void *p2, void *p3)
148	{
149		unsigned char buffer[1];
150		int hdr_len, data_len, ret;
151		struct net_buf *buf;
152		bool discardable;
153		uint8_t type;
154		uint8_t event;
155		union {
156			struct bt_hci_cmd_hdr cmd;
157			struct bt_hci_acl_hdr acl;
158			struct bt_hci_iso_hdr iso;
159		} hdr;
160	
161		for (;;) {
162			ret = h4_recv_data(&type, 1);
163			if (ret != 1) {
164				LOG_ERR("Receiving type failed (err %d)", ret);
165				break;
166			}
167	
168			if (!valid_type(type)) {
169				LOG_ERR("Invalid type received (type 0x%02x)", type);
170				break;
171			}
172	
173			hdr_len = hdrlen(type);
174	
175			ret = h4_recv_data((uint8_t *)&hdr, hdr_len);
176			if (ret != hdr_len) {
177				LOG_ERR("Receiving hdr failed (err %d)", ret);
178				break;
179			}
180	
181			data_len = get_len(&hdr, type);
182	
183			buf = bt_buf_get_tx(BT_BUF_H4, K_NO_WAIT,
184					    &type, sizeof(type));
185			if (!buf) {
186				LOG_ERR("No available command buffers!");
187				break;
188			}
189	
190			net_buf_add_mem(buf, &hdr, hdr_len);
191	
192			ret = h4_recv_data(buf->data + hdr_len, data_len);
193			if (ret != data_len) {
194				LOG_ERR("Receiving payload failed (err %d)", ret);
195				break;
196			}
197	
198			net_buf_add(buf, data_len);
199	
200	#ifdef CONFIG_BT_H4_DEBUG
201			h4_data_dump("BT H4 RX", type, buf->data, hdr_len + data_len);
202	#endif
203			ret = bt_send(buf);
204			if (ret) {
205				LOG_ERR("Unable to send (err %d)", ret);
206				break;
207			}
208	
209			k_yield();
210		}
211	
212		BT_ASSERT(false);
213	}
214	
215	static int h4_open(void)
216	{
217		int ret;
218	
219		ret = file_open(&g_filep, CONFIG_BT_UART_H4_ON_DEV_NAME, O_RDWR | O_BINARY);
220		if (ret < 0) {
221			return ret;
222		}
223	
224		ret = (int)k_thread_create(&tx_thread_data, tx_thread_stack,
225				K_THREAD_STACK_SIZEOF(tx_thread_stack),
226				h4_tx_thread, NULL, NULL, NULL,
227				K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
228	
229		if (ret < 0) {
230			file_close(&g_filep);
231			return ret;
232		}
233	
234		k_thread_name_set(&tx_thread_data, "BT H4 TX");
235	
236		return 0;
237	}
238	
239	static int h4_send(struct net_buf *buf)
240	{
241		uint8_t type;
242		int ret;
243	
244	#ifdef CONFIG_BT_H4_DEBUG
245	if (buf->data[1] != 0x3e)
246		h4_data_dump("BT H4 TX", buf->data[0], buf->data + 1, buf->len - 1);
247	#endif
248	
249		ret = h4_send_data(buf->data, buf->len);
250		if (ret != buf->len) {
251			ret = -EINVAL;
252		}
253	
254		net_buf_unref(buf);
255	
256		return ret < 0 ? ret : 0;
257	}
258	
259	static void rx_thread(void *p1, void *p2, void *p3)
260	{
261		static K_FIFO_DEFINE(rx_queue);
262		int err;
263	
264		/* Enable the raw interface, this will in turn open the HCI driver */
265		bt_enable_raw(&rx_queue);
266		
267		err = h4_open();
268		if (err) {
269			LOG_ERR("bt tx open failed (err %d)", err);
270			return;
271	    	}
272	
273		while(true) {
274			struct net_buf *buf;
275	
276			buf = net_buf_get(&rx_queue, K_FOREVER);
277	
278			err = h4_send(buf);
279			__ASSERT_NO_MSG(err == 0);
280	
281			k_yield();
282		}
283	
284	    	return;
285	}
286	
287	int main(int argc, char *argv[])
288	{
289		K_SEM_DEFINE(wait, 0, 1);
290	
291		k_thread_create(&thread_data, thread_stack,
292				K_THREAD_STACK_SIZEOF(thread_stack),
293				rx_thread, NULL, NULL, NULL,
294				K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
295	
296		k_thread_name_set(&thread_data, "BT Thread");
297	
298		return k_sem_take(&wait, K_FOREVER);
299	}

